'use strict';
// Local gameplay systems. Replace the social adapter when real accounts are connected.
const HOUR=3600000, PACK_COOLDOWN=23*HOUR;
const extraItems=[
 {id:'kunai',name:'Scout Kunai',slot:'weapon',a:5,d:1,price:15,icon:13,desc:'A stack of throwing blades. Some missions consume these.'},
 {id:'bomb',name:'Ember Paper Seal',slot:'tool',a:9,d:1,price:25,icon:2,desc:'An explosive seal used during infiltration contracts.'},
 {id:'ration',name:'Trail Ration',slot:'supply',a:0,d:0,price:10,icon:6,desc:'Field supplies consumed on longer missions.'},
 {id:'smoke',name:'Mist Capsule',slot:'tool',a:3,d:8,price:20,icon:8,desc:'Concealment gear and an extraction mission supply.'},
 {id:'saber',name:'Embersteel Saber',slot:'weapon',a:28,d:5,price:800,icon:11,desc:'A heavier sword for veteran squads.'},
 {id:'plate',name:'Nightguard Armor',slot:'armor',a:3,d:30,price:850,icon:3,desc:'Reinforced protection for dangerous deployments.'},
 {id:'ward',name:'Storm Ward',slot:'charm',a:12,d:20,price:900,icon:14,desc:'A protective charm with a trace of storm spirit.'},
 {id:'elixir',name:'Spirit Elixir',slot:'supply',a:0,d:0,price:150,icon:8,desc:'Consume to restore 20 spirit, up to your normal maximum.'}
];
items.forEach(i=>{i.slot={blade:'weapon',coat:'armor',needles:'tool',charm:'charm'}[i.id];i.icon={blade:11,coat:12,needles:13,charm:14}[i.id]});items.push(...extraItems);
const demoRecruits=[{id:'aya',name:'Aya Reed',role:'River tracker',a:28,d:25,face:2,price:0},{id:'taro',name:'Taro Flint',role:'Stone sentinel',a:20,d:40,face:3,price:0},{id:'sora',name:'Sora Nightfall',role:'Silent courier',a:38,d:20,face:1,price:0}];companions.push(...demoRecruits);
const ELEMENTS=['Storm','Flame','River','Stone','Wind'];
const storyChapters=[
 {id:'siege',name:'The Siege of Hollow Falls',level:3,desc:'A warning bell. A broken gate. Five contracts to defend your home.',missions:[0,4,15,18,22],reward:900},
 {id:'lantern',name:'The Lost Lantern Expedition',level:8,desc:'Follow a vanished envoy beyond the mist and recover the province seal.',missions:[30,33,45,48,52],reward:2200}
];
const dutyTypes=[{id:'patrol',name:'Night Watch',duration:5*60000,cost:2,coins:90,xp:12,desc:'Patrol the village walls for five minutes.'},{id:'archive',name:'Archive Service',duration:15*60000,cost:4,coins:240,xp:25,desc:'Restore the council scrolls over fifteen minutes.'},{id:'escort',name:'Caravan Guard',duration:30*60000,cost:6,coins:500,xp:45,desc:'Escort a supply caravan for thirty minutes.'}];
function setupSystems(){
 if(s.systemVersion!==1){for(const id of Object.keys(s.items))s.items[id]=s.items[id]===true?1:Math.max(0,Math.floor(Number(s.items[id])||0));for(const id of ['kunai','ration','bomb','smoke'])s.items[id]=(s.items[id]||0)+10;s.systemVersion=1;log('Starter supplies delivered: 10 of each mission supply.')}
 s.element??='Storm';s.healthBonus??=0;s.spiritBonus??=0;s.staminaBonus??=0;s.story??={};s.councilClaims??=[];s.gifts??={receivedAt:0,sent:{},freeAt:0};s.gifts.sent??={};s.duty??=null;s.dutiesDone??=0;s.forum??=[];s.teamFeed??=[];s.recruits??=[];s.autoBuy??=false;s.autoBuyUnlocked??=false;s.referralCode??='SL-'+Math.random().toString(36).slice(2,10).toUpperCase();save();
}
setupSystems();
const qty=id=>Math.max(0,Number(s.items[id])||0);
function addItem(id,n){s.items[id]=qty(id)+n}
function teamEvent(text){s.teamFeed.unshift({text,time:Date.now()});s.teamFeed=s.teamFeed.slice(0,30)}
function equipmentSet(stat){const result=[];for(const slot of ['weapon','armor','tool','charm']){let left=1+s.team.length;for(const i of items.filter(i=>i.slot===slot&&qty(i.id)>0).sort((a,b)=>b[stat]-a[stat]||a.price-b.price)){const n=Math.min(left,qty(i.id));if(n){result.push({item:i,n});left-=n}if(!left)break}}return result}
power=function(){const attackSet=equipmentSet('a'),defenseSet=equipmentSet('d'),ia=attackSet.reduce((n,e)=>n+e.item.a*e.n,0),id=defenseSet.reduce((n,e)=>n+e.item.d*e.n,0);let ta=0,td=0,ca=0,cd=0;techniques.forEach(t=>{ta+=t.a*(s.tech[t.id]||0);td+=t.d*(s.tech[t.id]||0)});companions.filter(c=>s.team.includes(c.id)).forEach(c=>{ca+=Math.round(c.a*.3);cd+=Math.round(c.d*.3)});return {a:s.atk+ia+ta+ca,d:s.def+id+td+cd,ia,id,ta,td,ca,cd,attackSet,defenseSet}};
function loadoutHTML(){const p=power();return `<div class="system-grid">${[['Best attack equipment',p.attackSet,'a'],['Best defense equipment',p.defenseSet,'d']].map(([name,set,stat])=>`<article class="card"><div class="eyebrow">AUTOMATIC LOADOUT</div><h3>${name}</h3><p>Up to ${1+s.team.length} of each slot: weapon, armor, tool and charm.</p>${set.length?set.map(e=>`<div class="stat-line"><span>${e.n} × ${e.item.name}</span><b>+${e.n*e.item[stat]}</b></div>`).join(''):'<p>No equipment owned yet.</p>'}</article>`).join('')}</div>`}
function buyItem(id,n){const i=items.find(i=>i.id===id);if(!i||!Number.isSafeInteger(n)||n<1||n>1000)return false;const cost=i.price*n;if(s.coins<cost){toast('Not enough copper.');return false}s.coins-=cost;addItem(id,n);log('Bought '+n+' × '+i.name+'.');return true}
equipmentView=function(){ $('#view').innerHTML=title('THE ARMORY','Stock your squad. Carry the right tools for every contract.')+loadoutHTML()+`<div class="grid equipment-grid">${items.map(i=>`<article class="card">${uiIcon(i.icon,'equipment-art')}<div class="eyebrow">${i.slot.toUpperCase()} · OWNED ${fmt(qty(i.id))}</div><h3>${i.name}</h3><p>${i.desc}</p><div class="cost">${i.a} Attack · ${i.d} Defense · ${fmt(i.price)} Copper each</div><label for="qty-${i.id}">Quantity</label><input id="qty-${i.id}" type="number" min="1" max="1000" step="1" value="1"><div class="system-actions"><button class="gold" data-system="buy" data-id="${i.id}">Buy</button>${i.id==='elixir'?`<button class="outline" data-system="elixir" ${qty(i.id)<1?'disabled':''}>Use +20 Spirit</button>`:''}</div></article>`).join('')}</div><div class="combat-note">Each squad member can use one item per slot. Best attack and defense sets are calculated independently. Extra copies stay in your inventory; mission supplies are consumed.</div>` };
function missionRequirement(m){const index=missions.indexOf(m),id=['kunai','ration','bomb','smoke'][index%4],n=1+Math.floor(grades.findIndex(g=>g.id===m.grade)/2);return {id,n,item:items.find(i=>i.id===id)}}
function missionSupply(m){const r=missionRequirement(m),missing=Math.max(0,r.n-qty(r.id)),price=missing*r.item.price;return {...r,missing,price,ready:missing===0||(s.autoBuyUnlocked&&s.autoBuy&&s.coins>=price)}}
function canMission(m){return s.level>=m.level&&s.stamina>=m.cost&&missionSupply(m).ready}
function performMission(id){regen();const m=missions.find(m=>m.id===id);if(!m)return false;const req=missionSupply(m);if(!canMission(m)){toast(!req.ready?'Buy the required supplies in the Armory.':'Not enough stamina or mission level locked.');return false}if(req.missing){s.coins-=req.price;addItem(req.id,req.missing)}addItem(req.id,-req.n);s.stamina-=m.cost;const reward=Math.round(m.coins*((s.missions[m.id]||0)>=5?1.2:1));s.missions[m.id]=(s.missions[m.id]||0)+1;gain(m.xp,reward);log('Completed '+m.name+'.');lastResults.missions={type:'mission',id:m.id,grade:m.grade,name:m.name,cost:m.cost,xp:m.xp,coins:reward,mastery:s.missions[m.id],supply:req.item.name,supplyN:req.n,autoCost:req.price};return true}
missionView=function(){const grade=selectedGrades.missions;$('#view').innerHTML=catalogHeader('missions')+`<div class="system-banner">${uiIcon(1)}<span>Missions use <b>Stamina</b> and supplies. AutoBuy: <b>${s.autoBuyUnlocked?(s.autoBuy?'ON':'OFF'):'LOCKED'}</b></span><button class="text-button" data-tab="council">Council →</button></div><div class="catalog-list">${missions.filter(m=>m.grade===grade).map(m=>{const done=s.missions[m.id]||0,r=missionSupply(m),locked=s.level<m.level;return `<article class="catalog-row">${entryArt(m)}<div class="catalog-content"><div class="eyebrow">GRADE ${m.grade}</div><h3>${m.name}</h3><p>${m.desc}</p><div class="catalog-mastery"><span>${done>=5?'Expert':'Mastery'}: ${Math.min(done,5)*20}%</span><div class="classic-progress"><i style="width:${Math.min(done,5)*20}%"></i></div></div></div><div class="catalog-action"><div class="catalog-rewards"><b>${Math.round(m.coins*(done>=5?1.2:1))} Copper</b><b>${m.xp} Experience</b></div><div class="catalog-requirement">${m.cost} Stamina · Level ${m.level}<br>${r.n} × ${r.item.name} (${qty(r.id)} owned)${r.missing&&s.autoBuyUnlocked&&s.autoBuy?'<br>AutoBuy: '+r.price+' Copper':''}</div><button class="classic-again" data-system="mission" data-id="${m.id}" ${canMission(m)?'':'disabled'}>${locked?'Level '+m.level+' required':s.stamina<m.cost?'Need '+m.cost+' stamina':!r.ready?'Need supplies':'Do mission'}</button></div></article>`}).join('')}</div><div class="combat-note">Five completions earn Expert mastery and +20% copper. Stamina recovers by 1 per minute. Supplies are consumed each run.</div>`};
const baseResult=renderResult;
renderResult=function(){baseResult();const r=lastResults[tab];if(!r||r.grade&&r.grade!==selectedGrades[tab])return;const el=$('#action-result');if(!el)return;if(r.type==='mission'&&r.supply)el.insertAdjacentHTML('beforeend',`<p>Supplies spent: ${r.supplyN} × ${escapeHTML(r.supply)}${r.autoCost?' · AutoBuy spent '+r.autoCost+' Copper':''}</p>`);if(r.type==='fight'&&r.loot)el.insertAdjacentHTML('beforeend',`<p>Item found: 1 × ${escapeHTML(r.loot)}</p>`);if(r.type==='mission'){const m=missions.find(m=>m.id===r.id),b=el.querySelector?.('[data-mission]');if(b&&!canMission(m)){b.disabled=true;if(!missionSupply(m).ready)el.insertAdjacentHTML('beforeend','<p>More supplies required. Visit the Armory or enable AutoBuy.</p>')}}};
const baseFight=fight;
fight=function(id){const before=s.wins+s.losses;baseFight(id);if(s.wins+s.losses===before)return;const r=lastResults.arena;r.equipment=power().attackSet.map(e=>e.n+' × '+e.item.name);if(r.won&&Math.random()<.18){const drop=['kunai','bomb','smoke','elixir'][Math.floor(Math.random()*4)];addItem(drop,1);r.loot=items.find(i=>i.id===drop).name;log('Found '+r.loot+'.')}if(s.team.length){const ally=companions.find(c=>c.id===s.team[(s.wins+s.losses)%s.team.length]);if(ally)teamEvent(ally.name+' supported your fight against '+opponents.find(o=>o.id===id).name+'.')}save();render()};
const baseArena=arena;arena=function(){baseArena();$('#view').insertAdjacentHTML('beforeend',loadoutHTML())};
function allocateStat(id){const costs={atk:1,def:1,healthBonus:1,spiritBonus:1,staminaBonus:2};if(!costs[id]||s.points<costs[id])return false;s.points-=costs[id];s[id]+=id==='staminaBonus'?1:5;return true}
function profileView(){const p=power(),record=[['Missions completed',Object.values(s.missions).reduce((a,b)=>a+b,0)],['Fights won',s.wins],['Fights lost',s.losses],['Ninjas killed',s.kills],['Deaths',s.deaths],['Jutsus learned',Object.values(s.tech).filter(n=>n>0).length],['Duties completed',s.dutiesDone]];$('#view').innerHTML=title('YOUR LEGEND',rank()+' · Level '+s.level+' · '+s.element+' affinity')+`<div class="system-grid"><article class="card"><h3>Identity</h3><label for="name-input">Shinobi name</label><input id="name-input" maxlength="20" value="${escapeHTML(s.name)}"><label for="element-choice">Elemental identity</label><select id="element-choice">${ELEMENTS.map(e=>`<option ${s.element===e?'selected':''}>${e}</option>`).join('')}</select><p>Your element is a profile identity; it does not alter combat stats.</p><button class="gold" data-system="identity">Save identity</button></article><article class="card"><div class="eyebrow">${s.points} BONUS POINTS AVAILABLE</div><h3>Develop your stats</h3><p>Level up for 3 points. Upgrades raise maximum resources; healing fills them.</p>${[['atk','Attack',s.atk,5,1],['def','Defense',s.def,5,1],['healthBonus','Health',maxHealth(),5,1],['spiritBonus','Spirit',maxEnergy(),5,1],['staminaBonus','Stamina',maxStamina(),1,2]].map(([id,name,v,n,c])=>`<div class="stat-line"><span>${name}: <b>${v}</b></span><button class="outline" data-system="stat" data-id="${id}" ${s.points<c?'disabled':''}>+${n} · ${c} pt</button></div>`).join('')}</article><article class="card"><h3>Lifetime record</h3>${record.map(([k,v])=>`<div class="stat-line"><span>${k}</span><b>${fmt(v)}</b></div>`).join('')}</article><article class="card"><h3>Combat breakdown</h3>${[['Base',s.atk,s.def],['Equipment',p.ia,p.id],['Jutsus',p.ta,p.td],['Team',p.ca,p.cd],['Total',p.a,p.d]].map(([k,a,d])=>`<div class="stat-line"><span>${k}</span><b>${fmt(a)} ATK / ${fmt(d)} DEF</b></div>`).join('')}<button class="outline" data-tab="council">Hospital & village services →</button></article></div><h2>Your learned jutsus</h2><div class="learned-grid">${techniques.filter(t=>s.tech[t.id]).map(t=>`<article class="card">${entryArt(t)}<h3>${t.name}</h3><p>${s.tech[t.id]>=5?'Expert':'Mastery '+s.tech[t.id]+'/5'} · Grade ${t.grade}</p></article>`).join('')||'<p>No jutsus learned yet. Visit the Jutsu Hall.</p>'}</div>`}
function storyView(){ $('#view').innerHTML=title('PROVINCE CHRONICLES','Complete each chapter in order. Every contract consumes stamina and field supplies.')+storyChapters.map(ch=>{const progress=s.story[ch.id]||0,finished=progress>=ch.missions.length,m=missions[ch.missions[Math.min(progress,ch.missions.length-1)]],req=missionSupply(m),level=Math.max(ch.level,m.level);return `<article class="card story-card">${entryArt(m)}<div><div class="eyebrow">CHAPTER · LEVEL ${ch.level}+</div><h2>${ch.name}</h2><p>${ch.desc}</p><ol class="story-steps">${ch.missions.map((index,i)=>`<li class="${i<progress?'done':i===progress?'current':''}">${i<progress?'✓ ':''}${missions[index].name}</li>`).join('')}</ol><p>Chapter reward: ${ch.reward} Copper + 2 bonus points.</p>${finished?'<span class="badge">CHAPTER COMPLETE</span>':`<p>Next: <b>${m.name}</b> · ${m.cost} Stamina · ${req.n} × ${req.item.name}<br>Contract reward: ${m.xp} XP · ${Math.round(m.coins*((s.missions[m.id]||0)>=5?1.2:1))} Copper · Level ${level}</p><button class="gold" data-system="story" data-id="${ch.id}" ${s.level<level||!canMission(m)?'disabled':''}>${s.level<level?'Requires level '+level:!req.ready?'Need supplies':'Complete next contract'}</button>`}</div></article>`}).join('') }
function completeStory(id){const ch=storyChapters.find(c=>c.id===id);if(!ch||s.level<ch.level)return false;const n=s.story[id]||0;if(n>=ch.missions.length||!performMission(missions[ch.missions[n]].id))return false;s.story[id]=n+1;if(n+1===ch.missions.length){s.coins+=ch.reward;s.points+=2;log('Finished '+ch.name+' · '+ch.reward+' Copper and 2 points.')}toast(n+1===ch.missions.length?'Chapter complete!':'Contract complete · '+(n+1)+' / '+ch.missions.length);return true}
function remaining(ms){const seconds=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(seconds/3600)}h ${Math.floor(seconds/60)%60}m ${seconds%60}s`}
function dutiesView(){const job=s.duty,active=job?dutyTypes.find(d=>d.id===job.id):null;$('#view').innerHTML=title('VILLAGE DUTIES','Earn copper and experience while you serve Hollow Falls.')+(active?`<article class="card"><div class="eyebrow">CURRENT ASSIGNMENT</div><h2>${active.name}</h2><p>Time remaining: <b data-countdown="${job.ends}">${remaining(job.ends-Date.now())}</b></p><p>${active.coins} Copper · ${active.xp} Experience</p><button class="gold" data-system="claimDuty" ${Date.now()<job.ends?'disabled':''}>Claim completed duty</button></article>`:'')+`<div class="grid">${dutyTypes.map(d=>`<article class="card">${uiIcon(1,'equipment-art')}<h3>${d.name}</h3><p>${d.desc}</p><p>${d.cost} Stamina · ${d.coins} Copper · ${d.xp} XP</p><button class="gold" data-system="duty" data-id="${d.id}" ${job||s.stamina<d.cost?'disabled':''}>Start duty</button></article>`).join('')}</div><p class="combat-note">One duty at a time. The timer continues while you are away; collect the reward when you return.</p>` }
function startDuty(id){const d=dutyTypes.find(d=>d.id===id);if(!d||s.duty||s.stamina<d.cost)return false;s.stamina-=d.cost;s.duty={id,ends:Date.now()+d.duration};return true}
function claimDuty(){if(!s.duty||Date.now()<s.duty.ends)return false;const d=dutyTypes.find(d=>d.id===s.duty.id);s.duty=null;s.dutiesDone++;gain(d.xp,d.coins);log('Completed '+d.name+'.');return true}
function councilView(){ $('#view').innerHTML=title('VILLAGE COUNCIL','Develop your shinobi and prepare for the next expedition.')+`<div class="system-grid"><article class="card">${uiIcon(7,'equipment-art')}<h3>The village doctor</h3><p>Health: ${s.hp} / ${maxHealth()}. Restore your health to return to battle.</p><div class="system-actions"><button class="gold" data-action="heal" ${s.hp>=maxHealth()?'disabled':''}>Heal · 75 Copper</button><button class="outline" data-action="rest">Full rest · 150 Copper</button></div><p>Full rest restores health, spirit and stamina to normal maxima. An active spirit overfill is retained.</p></article><article class="card">${uiIcon(1,'equipment-art')}<h3>Mission AutoBuy</h3><p>Purchase only missing mission supplies automatically when you start a contract. Costs are displayed before you act.</p><button class="gold" data-system="autobuy" ${!s.autoBuyUnlocked&&s.coins<1000?'disabled':''}>${s.autoBuyUnlocked?(s.autoBuy?'Disable AutoBuy':'Enable AutoBuy'):'Unlock · 1,000 Copper'}</button></article><article class="card">${uiIcon(6,'equipment-art')}<h3>Province bank</h3><p>Wallet: ${fmt(s.coins)} Copper<br>Bank: ${fmt(s.bank)} Copper</p><p>Move copper in or out with no fee.</p><button class="gold" data-action="bank">Open bank</button></article><article class="card"><h3>Rank commendations</h3><p>Claim 2 bonus stat points once at each milestone.</p>${[3,5,8,12,16].map(n=>`<div class="stat-line"><span>Level ${n} · 2 points</span><button class="outline" data-system="commend" data-id="${n}" ${s.level<n||s.councilClaims.includes(n)?'disabled':''}>${s.councilClaims.includes(n)?'Claimed':s.level<n?'Locked':'Claim'}</button></div>`).join('')}</article></div>` }
function recruit(id){const c=companions.find(c=>c.id===id);if(!c||s.team.includes(id)||s.coins<c.price)return false;s.coins-=c.price;s.team.push(id);s.energy=Math.min(maxEnergy(),s.energy+5);if(demoRecruits.some(x=>x.id===id))s.recruits.push(id);teamEvent(c.name+' joined your team. +5 maximum spirit and +5 spirit.');log(c.name+' joined your team.');return true}
teamView=function(){const link=(globalThis.location?.origin||'https://veilstorm-shinobi.mihoiantun715.chatgpt.site')+'/?ref='+encodeURIComponent(s.referralCode);$('#view').innerHTML=title('YOUR INNER CIRCLE','Build the team that stands beside your legend.')+`<div class="system-banner"><b>LOCAL SOCIAL DEMO</b><span>These recruits are simulated allies. Invitations and gifts do not reach real players yet.</span></div><div class="team-summary"><span>${uiIcon(4)}<b>${s.team.length}</b> team members</span><span>30% stat support · +5 maximum Spirit each</span></div><article class="card"><h3>Recruitment link</h3><p>Your referral link is ready for future account integration. For now, use the demo recruits below to test recruitment rewards.</p><label for="referral-link">Your invitation link</label><input id="referral-link" readonly value="${escapeHTML(link)}"><button class="outline" data-system="copyInvite">Copy link</button></article><div class="grid team-grid">${companions.map(c=>`<article class="card team-card"><div class="companion-portrait face f${c.face}"><span class="companion-role">${c.role}</span></div><div class="companion-body"><div class="eyebrow">${demoRecruits.some(d=>d.id===c.id)?'DEMO PLAYER RECRUIT':'VILLAGE COMPANION'}</div><h3>${c.name}</h3><p>${c.a} Attack · ${c.d} Defense<br>Support: +${Math.round(c.a*.3)} ATK / +${Math.round(c.d*.3)} DEF</p><button class="gold" data-system="recruit" data-id="${c.id}" ${s.team.includes(c.id)||s.coins<c.price?'disabled':''}>${s.team.includes(c.id)?'In your team':c.price?'Recruit · '+c.price+' Copper':'Recruit demo teammate'}</button></div></article>`).join('')}</div><article class="card"><h3>Team activity</h3>${s.teamFeed.length?s.teamFeed.map(e=>`<p>${escapeHTML(e.text)} <small class="muted">${new Date(e.time).toLocaleString()}</small></p>`).join(''):'<p>Recruit an ally and fight to build your team history.</p>'}</article>` };
function claimPack(){if(!s.team.length||Date.now()-s.gifts.receivedAt<PACK_COOLDOWN)return false;s.gifts.receivedAt=Date.now();s.energy=Math.floor(maxEnergy()*1.25);teamEvent('A demo teammate sent you a Spirit Pack. Spirit filled to 125%.');return true}
function freeGift(){if(Date.now()-s.gifts.freeAt<PACK_COOLDOWN)return false;s.gifts.freeAt=Date.now();const id=['kunai','bomb','smoke','elixir'][Math.floor(Math.random()*4)],n=id==='elixir'?1:5;addItem(id,n);s.coins+=100;log('Free gift: '+n+' × '+items.find(i=>i.id===id).name+' and 100 Copper.');toast('Gift claimed: '+n+' × '+items.find(i=>i.id===id).name+' + 100 Copper');return true}
function giftsView(){const wait=s.gifts.receivedAt+PACK_COOLDOWN-Date.now(),freeWait=s.gifts.freeAt+PACK_COOLDOWN-Date.now();$('#view').innerHTML=title('GIFTS & SPIRIT PACKS','A small gesture can fuel a long journey.')+`<div class="system-banner"><b>LOCAL SOCIAL DEMO</b><span>Pack sending and receiving are simulated; no messages are sent.</span></div><div class="system-grid"><article class="card">${uiIcon(8,'equipment-art')}<h3>Receive a Spirit Pack</h3><p>Fill spirit to <b>125% of your normal maximum</b>. One received pack every 23 hours. Excess spirit remains until spent; it does not regenerate above your normal cap.</p><p>${s.energy} / ${maxEnergy()} Spirit</p><button class="gold" data-system="pack" ${wait>0||!s.team.length?'disabled':''}>${!s.team.length?'Recruit a teammate first':wait>0?'Pack on cooldown':'Receive demo teammate pack'}</button>${wait>0?`<p data-countdown="${s.gifts.receivedAt+PACK_COOLDOWN}">${remaining(wait)}</p>`:''}</article><article class="card">${uiIcon(6,'equipment-art')}<h3>Free supply gift</h3><p>Claim a random supply bundle and 100 Copper every 23 hours. No video required.</p><button class="gold" data-system="freeGift" ${freeWait>0?'disabled':''}>${freeWait>0?'Gift claimed':'Open free gift'}</button>${freeWait>0?`<p data-countdown="${s.gifts.freeAt+PACK_COOLDOWN}">${remaining(freeWait)}</p>`:''}</article></div><article class="card"><h3>Send a teammate a pack</h3><p>Send once per teammate every 23 hours in this local demo.</p>${companions.filter(c=>s.team.includes(c.id)).map(c=>{const wait=(s.gifts.sent[c.id]||0)+PACK_COOLDOWN-Date.now();return `<div class="stat-line"><span>${c.name}${wait>0?`<small data-countdown="${s.gifts.sent[c.id]+PACK_COOLDOWN}">${remaining(wait)}</small>`:''}</span><button class="outline" data-system="sendPack" data-id="${c.id}" ${wait>0?'disabled':''}>${wait>0?'Sent':'Send demo pack'}</button></div>`}).join('')||'<p>Recruit teammates first.</p>'}</article>` }
let rankingMetric='level';
function rankingsView(){const rows=[{name:s.name,level:s.level,wins:s.wins,kills:s.kills,you:true},...opponents.map(o=>({name:o.name,level:o.level,wins:rivalState(o.id).wins||0,kills:rivalState(o.id).kills||0}))].sort((a,b)=>b[rankingMetric]-a[rankingMetric]);$('#view').innerHTML=title('PROVINCE RANKINGS','Local demo standings: you and the practice rivals.')+`<div class="tabs">${['level','wins','kills'].map(k=>`<button class="${k===rankingMetric?'active':''}" data-system="ranking" data-id="${k}">${k.toUpperCase()}</button>`).join('')}</div><div class="table-scroll"><table class="system-table"><thead><tr><th>Rank</th><th>Shinobi</th><th>Level</th><th>Wins</th><th>Kills</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.you?'you':''}"><td>${i+1}</td><td>${escapeHTML(r.name)}${r.you?' · YOU':' · AI'}</td><td>${r.level}</td><td>${r.wins}</td><td>${r.kills}</td></tr>`).join('')}</tbody></table></div><p class="combat-note">These are saved local results, not a global leaderboard. AI wins count their victories against you.</p>` }
let forumOpen=null;
function forumView(){const thread=s.forum.find(t=>t.id===forumOpen);$('#view').innerHTML=title('VILLAGE FORUM','A local noticeboard for your notes, strategy and future community.')+`<div class="system-banner"><b>LOCAL DEMO</b><span>Posts are saved only in this browser. Nothing is published to other players.</span></div>`+(thread?`<article class="card"><button class="text-button" data-system="forumBack">← All topics</button><h2>${escapeHTML(thread.title)}</h2><p class="forum-copy">${escapeHTML(thread.body)}</p><p class="muted">${escapeHTML(thread.author)} · ${new Date(thread.time).toLocaleString()}</p>${thread.replies.map(r=>`<div class="forum-reply"><b>${escapeHTML(r.author)}</b><p class="forum-copy">${escapeHTML(r.body)}</p></div>`).join('')}<label for="forum-reply">Reply (max 1,000 characters)</label><textarea id="forum-reply" maxlength="1000" rows="3"></textarea><button class="gold" data-system="reply">Save local reply</button></article>`:`<div class="system-grid"><article class="card"><h3>Start a topic</h3><label for="forum-title">Title</label><input id="forum-title" maxlength="80"><label for="forum-body">Message</label><textarea id="forum-body" maxlength="2000" rows="5"></textarea><button class="gold" data-system="post">Save local topic</button></article><article class="card"><h3>Topics (${s.forum.length})</h3>${s.forum.map(t=>`<div class="forum-topic"><button class="text-button" data-system="topic" data-id="${t.id}">${escapeHTML(t.title)}</button><small>${escapeHTML(t.author)} · ${t.replies.length} replies</small></div>`).join('')||'<p>No topics yet. Add your first strategy note.</p>'}</article></div>`)}
globalThis.extraViews={story:storyView,duties:dutiesView,council:councilView,gifts:giftsView,ranks:rankingsView,forum:forumView};
function systemAction(action,id){
 switch(action){
 case 'buy':return buyItem(id,Number($('#qty-'+id).value));
 case 'elixir':if(qty('elixir')<1||s.energy>=maxEnergy())return false;addItem('elixir',-1);s.energy=Math.min(maxEnergy(),s.energy+20);return true;
 case 'mission':return performMission(id);
 case 'stat':return allocateStat(id);
 case 'identity':{const name=$('#name-input').value.trim(),element=$('#element-choice').value;if(name.length<3||name.length>20||!ELEMENTS.includes(element)){toast('Use a name with 3–20 characters.');return false}s.name=name;s.element=element;return true}
 case 'story':return completeStory(id);
 case 'duty':return startDuty(id);
 case 'claimDuty':return claimDuty();
 case 'autobuy':if(!s.autoBuyUnlocked){if(s.coins<1000)return false;s.coins-=1000;s.autoBuyUnlocked=true}s.autoBuy=!s.autoBuy;return true;
 case 'commend':{const n=Number(id);if(![3,5,8,12,16].includes(n)||s.level<n||s.councilClaims.includes(n))return false;s.councilClaims.push(n);s.points+=2;return true}
 case 'recruit':return recruit(id);
 case 'pack':return claimPack();
 case 'freeGift':return freeGift();
 case 'sendPack':{if(!s.team.includes(id)||Date.now()-(s.gifts.sent[id]||0)<PACK_COOLDOWN)return false;s.gifts.sent[id]=Date.now();teamEvent('You sent a demo Spirit Pack to '+companions.find(c=>c.id===id).name+'.');return true}
 case 'copyInvite':{const input=$('#referral-link');input.select();if(globalThis.navigator?.clipboard)navigator.clipboard.writeText(input.value).then(()=>toast('Invitation link copied.')).catch(()=>toast('Select and copy the invitation link.'));else toast('Select and copy the invitation link.');return false}
 case 'ranking':if(!['level','wins','kills'].includes(id))return false;rankingMetric=id;return true;
 case 'post':{const title=$('#forum-title').value.trim(),body=$('#forum-body').value.trim();if(!title||!body){toast('Enter a topic title and message.');return false}if(s.forum.length>=100){toast('Local topic limit reached (100).');return false}const t={id:'t-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),title:title.slice(0,80),body:body.slice(0,2000),author:s.name,time:Date.now(),replies:[]};s.forum.unshift(t);forumOpen=t.id;return true}
 case 'topic':forumOpen=id;return true;
 case 'forumBack':forumOpen=null;return true;
 case 'reply':{const t=s.forum.find(t=>t.id===forumOpen),body=$('#forum-reply').value.trim();if(!t||!body||t.replies.length>=100)return false;t.replies.push({author:s.name,body:body.slice(0,1000),time:Date.now()});return true}
 default:return false;
 }
}
// Capture replaces legacy purchase, stat and mission paths; these cannot double-charge.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;let action=b.dataset.system,id=b.dataset.id;if(!action&&b.dataset.mission){action='mission';id=b.dataset.mission}if(!action)return;e.preventDefault();e.stopImmediatePropagation();regen();if(systemAction(action,id)){save();render();if(action==='mission')revealResult()}},true);
const baseExpandedRender=render;
render=function(){baseExpandedRender();updateTimers()};
function updateTimers(){document.querySelectorAll('[data-countdown]').forEach(el=>{el.textContent=remaining(Number(el.dataset.countdown)-Date.now())});const res=$('#resources');if(!res)return;res.querySelectorAll('.res').forEach((el,i)=>{if(i<1||i>3)return;const values=[0,s.hp,s.energy,s.stamina],caps=[0,maxHealth(),maxEnergy(),maxStamina()];let small=el.querySelector('.regen-clock');if(!small){small=document.createElement('small');small.className='regen-clock';el.appendChild(small)}small.textContent=values[i]>=caps[i]?(i===2&&values[i]>caps[i]?'OVERFILLED':'FULL'):'Next +'+[0,2,3,1][i]+' in '+remaining(Math.max(0,60000-(Date.now()-s.last)))})}
setInterval(()=>{if(document.body.classList.contains('auth-open'))return;updateTimers();if((tab==='gifts'&&Array.from(document.querySelectorAll('[data-countdown]')).some(el=>Number(el.dataset.countdown)<=Date.now())))render()},1000);
$('#guide').onclick=()=>open(`<div class="eyebrow">SHINOBI FIELD GUIDE</div><h2>Your path through Hollow Falls</h2><p>Missions and fights use Stamina. Jutsus use Spirit. Missions also consume the supplies shown on each contract.</p><p>Buy inventory in bulk at the Armory. Each squad member can use one item per equipment slot. Best attack and defense sets are selected separately.</p><p>Spend level-up points in Profile. Stamina costs 2 points per +1; Attack, Defense, Health and Spirit cost 1 point per +5.</p><p>Combat deals at most 27 HP damage to either fighter. At 0 HP a shinobi cannot fight until healed or regenerated. Kills and deaths are recorded separately from wins and losses.</p><p>Complete story chapters, timed duties and Council commendations. Unlock AutoBuy for mission supplies, or visit the doctor and bank.</p><p>Recruit demo teammates, send Spirit Packs and collect a pack every 23 hours to reach 125% Spirit. Free gifts use a separate 23-hour timer.</p><p>All progress is local to this browser. Team recruitment, gifts, rankings and forum are demo systems until real accounts and multiplayer are connected.</p>`);
render();
